using Microsoft.EntityFrameworkCore;
class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // EF Core 9 removed Cosmos DB index support — indexes are managed via Azure portal.
        // modelBuilder.Entity<Blog>().HasIndex(b => b.Name);  // REMOVED: throws at runtime in 9.0

        // Breaking change 1: Discriminator property renamed from "Discriminator" to "$type".
        // To keep reading existing documents that use "Discriminator", restore the old name:
        modelBuilder.Entity<Blog>().HasDiscriminator<string>("Discriminator");

        // Breaking change 2: Id format changed from "EntityType|KeyValue" to just "KeyValue".
        // To keep reading existing documents with id "Blog|1", restore the old id format:
        modelBuilder.Entity<Blog>().HasPartitionKey(b => b.Id);
        modelBuilder.Entity<Blog>().Property(b => b.Id)
            .ToJsonProperty("id")
            .HasValueGenerator<LegacyCosmosIdGenerator>();
    }
}

